code='''from collections import Counter

def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    bg=Counter(x for row in g for x in row).most_common(1)[0][0]
    fg=Counter(x for row in g for x in row if x!=bg).most_common(1)[0][0]
    blocks=[]
    r=0
    while r<h:
        if all(x==bg for x in g[r]):
            r+=1; continue
        start=r
        while r<h and any(x!=bg for x in g[r]):
            r+=1
        blocks.append((start,[row[:] for row in g[start:r]]))
    if not blocks:
        return g
    # Short stripe objects encode a width-long run; color only the missing
    # cells within the run, leaving the trailing background untouched.
    if len(blocks)>=2 and all(len(b)==1 for _,b in blocks):
        for start,b in blocks:
            row=b[0]
            pos=[i for i,x in enumerate(row) if x==fg]
            if pos and len(pos)<w:
                left=min(pos)
                for c in range(left,min(w,left+w)):
                    if row[c]==bg:
                        g[start][c]=1
        return g
    if len(blocks)>=2 and all(len(b)==2 for _,b in blocks):
        for start,b in blocks:
            flat=[x for row in b for x in row]
            pos=[i for i,x in enumerate(flat) if x==fg]
            if pos and len(pos)<w:
                left=min(pos)
                for i in range(left,min(len(flat),left+w)):
                    if flat[i]==bg:
                        g[start+i//w][i%w]=1
        return g
    if len(blocks)>=2 and all(len(b)==len(blocks[0][1]) for _,b in blocks):
        # Choose the most complete block as the reference.
        counts=[sum(x!=bg for row in b for x in row) for _,b in blocks]
        ref_i=max(range(len(blocks)),key=lambda i:counts[i])
        ref_start,ref=blocks[ref_i]
        # For structured noisy panels, align the less-complete panel by a
        # one-cell horizontal shift before marking extra foreground cells.
        target_i=min((i for i in range(len(blocks)) if i!=ref_i),key=lambda i:counts[i])
        target_start,target=blocks[target_i]
        hh=len(ref)
        best=(0,None)
        for dx in range(-2,3):
            score=0
            for rr in range(hh):
                for c in range(w):
                    sc=c-dx
                    if 0<=sc<w:
                        score += (target[rr][c]==ref[rr][sc])
            if score>best[0]: best=(score,dx)
        dx=best[1] or 0
        # Directly matching panels: mark missing foreground in the less-full panel.
        direct=sum(target[rr][c]==ref[rr][c] for rr in range(hh) for c in range(w))
        aligned=best[0]
        if dx and aligned>direct+hh:
            for rr in range(hh):
                for c in range(1,w-1):
                    sc=c-dx
                    if 0<=sc<w and target[rr][c]==fg and ref[rr][sc]==bg:
                        g[target_start+rr][c]=1
        else:
            for rr in range(hh):
                for c in range(w):
                    if target[rr][c]==bg and ref[rr][c]!=bg:
                        g[target_start+rr][c]=1
        return g
    return g
'''
